CREATE TYPE "CorporateGraphNodeType" AS ENUM ('COMPANY', 'PERSON', 'TRUST', 'PARTNERSHIP', 'BRANCH', 'BANKING_RELATIONSHIP', 'LICENSE', 'TAX_REGISTRATION', 'OTHER');
CREATE TYPE "CorporateGraphRelationType" AS ENUM ('OWNS', 'CONTROLS', 'SUBSIDIARY_OF', 'BRANCH_OF', 'BANKS_WITH', 'LICENSED_BY', 'TAX_REGISTERED_WITH', 'RELATED_TO');
CREATE TYPE "CorporateRuleReviewStatus" AS ENUM ('UNREVIEWED', 'IN_REVIEW', 'VERIFIED', 'REJECTED', 'SUPERSEDED');
CREATE TYPE "CorporateRuleSeverity" AS ENUM ('INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL');
CREATE TABLE "CorporateGraphNode" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"clientId" TEXT,"name" TEXT NOT NULL,"nodeType" "CorporateGraphNodeType" NOT NULL DEFAULT 'COMPANY',"jurisdictionCode" TEXT,"entityType" TEXT,"registrationNumber" TEXT,"metadata" JSONB,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CorporateGraphNode_pkey" PRIMARY KEY ("id"),CONSTRAINT "CorporateGraphNode_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "CorporateGraphNode_organizationId_workspaceId_fkey" FOREIGN KEY ("organizationId","workspaceId") REFERENCES "Workspace"("organizationId","id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "CorporateGraphNode_clientId_workspaceId_fkey" FOREIGN KEY ("clientId","workspaceId") REFERENCES "Client"("id","workspaceId") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "CorporateGraphEdge" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"fromNodeId" TEXT NOT NULL,"toNodeId" TEXT NOT NULL,"relation" "CorporateGraphRelationType" NOT NULL,"ownershipPercent" DECIMAL(5,2),"notes" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CorporateGraphEdge_pkey" PRIMARY KEY ("id"),CONSTRAINT "CorporateGraphEdge_fromNodeId_fkey" FOREIGN KEY ("fromNodeId") REFERENCES "CorporateGraphNode"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "CorporateGraphEdge_toNodeId_fkey" FOREIGN KEY ("toNodeId") REFERENCES "CorporateGraphNode"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "CorporateComplianceRule" ("id" TEXT NOT NULL,"jurisdictionCode" TEXT NOT NULL,"entityType" TEXT NOT NULL,"ruleKey" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"frequency" TEXT,"severity" "CorporateRuleSeverity" NOT NULL DEFAULT 'MEDIUM',"sourceTitle" TEXT,"sourceUrl" TEXT,"sourceAuthority" TEXT,"sourceRetrievedAt" TIMESTAMP(3),"effectiveFrom" TIMESTAMP(3),"effectiveTo" TIMESTAMP(3),"evidenceClass" "EvidenceClass" NOT NULL DEFAULT 'E0',"reviewStatus" "CorporateRuleReviewStatus" NOT NULL DEFAULT 'UNREVIEWED',"reviewedByUserId" TEXT,"reviewedAt" TIMESTAMP(3),"version" INTEGER NOT NULL DEFAULT 1,"requiresProfessionalReview" BOOLEAN NOT NULL DEFAULT true,"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CorporateComplianceRule_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CorporateGraphNode_organizationId_workspaceId_idx" ON "CorporateGraphNode"("organizationId","workspaceId");
CREATE INDEX "CorporateGraphNode_clientId_workspaceId_idx" ON "CorporateGraphNode"("clientId","workspaceId");
CREATE INDEX "CorporateGraphNode_jurisdictionCode_entityType_idx" ON "CorporateGraphNode"("jurisdictionCode","entityType");
CREATE UNIQUE INDEX "CorporateGraphEdge_organizationId_workspaceId_fromNodeId_toNodeId_relation_key" ON "CorporateGraphEdge"("organizationId","workspaceId","fromNodeId","toNodeId","relation");
CREATE INDEX "CorporateGraphEdge_organizationId_workspaceId_fromNodeId_idx" ON "CorporateGraphEdge"("organizationId","workspaceId","fromNodeId");
CREATE INDEX "CorporateGraphEdge_organizationId_workspaceId_toNodeId_idx" ON "CorporateGraphEdge"("organizationId","workspaceId","toNodeId");
CREATE UNIQUE INDEX "CorporateComplianceRule_jurisdictionCode_entityType_ruleKey_version_key" ON "CorporateComplianceRule"("jurisdictionCode","entityType","ruleKey","version");
CREATE INDEX "CorporateComplianceRule_jurisdictionCode_entityType_active_reviewStatus_idx" ON "CorporateComplianceRule"("jurisdictionCode","entityType","active","reviewStatus");
CREATE INDEX "CorporateComplianceRule_sourceRetrievedAt_idx" ON "CorporateComplianceRule"("sourceRetrievedAt");
